code.cpp:
class Solution {
public:
    int minimumLengthEncoding(vector<string>& words) {
        set<string> uniqueWords(words.begin(), words.end());

        struct TrieNode {
            TrieNode* children[26] = {};
            bool hasChildren = false;
        };

        TrieNode* root = new TrieNode();
        vector<pair<string, TrieNode*>> nodes;

        for (const string& w : uniqueWords) {
            TrieNode* cur = root;
            for (int i = (int)w.size() - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                if (!cur->children[c]) {
                    cur->children[c] = new TrieNode();
                }
                cur->hasChildren = true;
                cur = cur->children[c];
            }
            nodes.push_back({w, cur});
        }

        int ans = 0;
        for (auto& p : nodes) {
            if (!p.second->hasChildren) {
                ans += (int)p.first.size() + 1;
            }
        }
        return ans;
    }
};
